@push('styles')
<style>
    .employee-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:25px}.employee-head h1{margin:5px 0;font-size:32px}.employee-head p,.employee-breadcrumb,.muted{margin:0;color:#64748b}.employee-breadcrumb{font-size:12px}.employee-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:22px}.employee-stat,.employee-card{background:#fff;border:1px solid #e2e8f0;border-radius:13px;box-shadow:0 1px 3px #0f172a12}.employee-stat{padding:19px}.employee-stat strong{display:block;font-size:29px}.employee-stat span{color:#64748b;font-size:12px}.employee-card{overflow:hidden}.employee-filters{display:grid;grid-template-columns:2fr 1fr auto;gap:10px;padding:18px;border-bottom:1px solid #e2e8f0}.employee-filters input,.employee-filters select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.employee-table-wrap{overflow-x:auto}.employee-table{width:100%;border-collapse:collapse}.employee-table th,.employee-table td{padding:14px 18px;text-align:left;border-bottom:1px solid #e2e8f0}.employee-table th{font-size:11px;text-transform:uppercase;color:#64748b;background:#f8fafc}.person{display:flex;align-items:center;gap:11px;min-width:180px}.avatar{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#E8F5F0;color:var(--green);font-size:11px;font-weight:800}.person small{display:block;color:#64748b;margin-top:3px}.employee-status{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border-radius:99px;font-size:12px;font-weight:700}.employee-status:before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor}.employee-status.active{background:#dcfce7;color:#166534}.employee-status.inactive{background:#f1f5f9;color:#475569}.employee-link{color:var(--green);font-weight:700;text-decoration:none}.employee-pagination{padding:18px}.employee-detail{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.employee-card-head{padding:17px 20px;border-bottom:1px solid #e2e8f0}.employee-card-head h2{margin:0;font-size:18px}.employee-card-body{padding:20px}.employee-info{display:grid;grid-template-columns:repeat(2,1fr);gap:19px}.employee-info small{display:block;color:#64748b;text-transform:uppercase;font-size:10px;font-weight:700;margin-bottom:5px}.account-empty{padding:16px;border-radius:9px;background:#f8fafc;color:#64748b}
    .employee-form{background:#fff;border:1px solid #e2e8f0;border-radius:13px;overflow:hidden}.employee-form-section{padding:24px}.employee-form-section+.employee-form-section{border-top:1px solid #e2e8f0}.employee-form-title h2{margin:0;font-size:18px}.employee-form-title p{margin:4px 0 18px;color:#64748b;font-size:13px}.employee-form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.employee-field.full{grid-column:1/-1}.employee-field label{display:block;margin-bottom:7px;font-size:13px;font-weight:700}.employee-field input,.employee-field select{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.employee-field input:focus,.employee-field select:focus{outline:3px solid #E8F5F0;border-color:var(--green)}.employee-field .invalid{border-color:var(--danger)}.employee-error{display:block;color:#b91c1c;font-size:12px;margin-top:5px}.employee-errors{margin:0 24px 20px;padding:14px;border-radius:9px;background:#fef2f2;color:#991b1b}.account-toggle{display:flex!important;align-items:center;gap:9px;padding:14px;border:1px solid #b8ddcf;border-radius:9px;background:#E8F5F0}.account-toggle input{width:auto}.account-note{padding:12px;border-radius:8px;background:#fffbeb;color:#92400e;font-size:12px}.employee-form-footer{display:flex;justify-content:flex-end;gap:10px;padding:18px 24px;border-top:1px solid #e2e8f0;background:#f8fafc}.required{color:var(--danger)}
    .employee-detail{grid-template-columns:repeat(2,minmax(0,1fr))}.employee-detail>*{min-width:0}.employee-info>*{min-width:0}.employee-info strong{display:block;overflow-wrap:anywhere}.employee-card-actions{display:flex;justify-content:flex-end;padding:16px 20px;border-top:1px solid var(--border);background:var(--bg)}.employee-card-actions .btn{min-height:40px;padding:9px 13px}.employee-permissions-card{margin-top:24px}.employee-permission-head{display:flex;align-items:center;justify-content:space-between}.employee-permission-head p{margin:5px 0 0;color:var(--muted);font-size:12px}.employee-permission-badge{flex:0 0 auto;padding:6px 10px;border-radius:999px;background:var(--pale);color:var(--green);font-size:11px;font-weight:800}.employee-standard-access{display:grid;gap:5px;padding:15px;border-left:3px solid var(--green);border-radius:8px;background:var(--pale)}.employee-standard-access strong{font-size:14px}.employee-standard-access span{color:#47635a;font-size:12px;line-height:1.5}.employee-permission-modules{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.employee-permission-module{min-width:0;padding:14px;border:1px solid var(--border);border-radius:9px;background:#fbfcfc}.employee-permission-module>div{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:9px}.employee-permission-module>div strong{font-size:13px}.employee-permission-module>div span{color:var(--muted);font-size:10px;white-space:nowrap}.employee-permission-module ul{margin:0;padding-left:18px;color:#475569;font-size:11px;line-height:1.6}.employee-permission-form{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:18px;margin-top:18px;padding-top:18px;border-top:1px solid var(--border)}.employee-permission-form .employee-field small{display:block;margin-top:7px;color:var(--muted);font-size:11px;line-height:1.45}.employee-permission-form-actions{display:flex;align-items:center;justify-content:flex-end;gap:12px;padding-bottom:1px}.employee-permission-form-actions>a{color:var(--green);font-size:12px;font-weight:700;white-space:nowrap}.employee-permission-form-actions .btn{white-space:nowrap}
    @media(max-width:1200px){.employee-detail{grid-template-columns:1fr}}@media(max-width:900px){.employee-summary{grid-template-columns:repeat(2,1fr)}.employee-permission-form{grid-template-columns:1fr}.employee-permission-form-actions{justify-content:space-between}}@media(max-width:650px){.employee-head,.employee-permission-head{align-items:flex-start;flex-direction:column}.employee-summary,.employee-filters,.employee-info,.employee-form-grid,.employee-permission-modules{grid-template-columns:1fr}.employee-field.full{grid-column:auto}.employee-form-footer{flex-direction:column-reverse}.employee-form-footer .btn,.employee-head>.btn,.employee-card-actions .btn{width:100%}.employee-card-actions{justify-content:stretch}.employee-permission-form-actions{align-items:stretch;flex-direction:column-reverse}.employee-permission-form-actions .btn{width:100%}.employee-permission-badge{margin-top:4px}}
</style>
@endpush
@push('styles')
<style>
.account-toggle span strong,.account-toggle span small{display:block}.account-toggle span small{margin-top:4px;color:#64748b;font-size:11px;font-weight:400}.role-explanation{padding:12px 14px;border-left:3px solid var(--gold);border-radius:7px;background:#FFF7E5;color:#6f541b;font-size:12px;line-height:1.5}.employee-form-title{padding-left:14px;border-left:3px solid var(--green)}.employee-form input:disabled,.employee-form select:disabled{background:#f1f5f9;color:#94a3b8;cursor:not-allowed}
</style>
@endpush
